using namespace std;
typedef long long ll;

int main() {
    string P;
    ll T;
    cin >> P >> T;

    int n = P.size();
    ll k = 0;  // 最长相等前后缀的长度

    // 枚举可能的前后缀长度
    for (int len = 1; len < n; len++) {
        string pre = P.substr(0, len);
        string suf = P.substr(n - len);
        if (pre == suf) {
            k = len; // 记录更长的长度
        }
    }

    // 最短充分序列长度 = n + (T-1) * (n - k)
    ll ans = n + (T - 1) * (n - k);
    cout << ans << endl;

    return 0;
}
